"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import styles from "./onboarding.module.css";

const AURA_TAGS = [
  "Adventurous", "Creative", "Analytical", "Spontaneous", 
  "Empathetic", "Ambitious", "Chill", "Outgoing"
];

export default function Onboarding() {
  const router = useRouter();
  const [step, setStep] = useState(1);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);

  const toggleTag = (tag: string) => {
    if (selectedTags.includes(tag)) {
      setSelectedTags(selectedTags.filter(t => t !== tag));
    } else if (selectedTags.length < 3) {
      setSelectedTags([...selectedTags, tag]);
    }
  };

  const handleNext = () => {
    if (step < 3) setStep(step + 1);
    else router.push("/discover");
  };

  return (
    <main className="flex-center" style={{ minHeight: "100vh", backgroundColor: "var(--bg-color)" }}>
      <div className={`glass-card ${styles.onboardingCard} animate-fade-in`}>
        <div className={styles.progress}>
          <div className={styles.progressBar} style={{ width: `${(step / 3) * 100}%` }}></div>
        </div>

        {step === 1 && (
          <div className="animate-fade-in">
            <h2 className="text-gradient">Who are you?</h2>
            <p className={styles.subtitle}>Let's start with the basics.</p>
            
            <div className={styles.formGroup}>
              <label>First Name</label>
              <input type="text" className={styles.input} placeholder="Enter your name" />
            </div>
            
            <div className={styles.formGroup}>
              <label>I identify as</label>
              <select className={styles.input}>
                <option value="">Select gender</option>
                <option value="man">Man</option>
                <option value="woman">Woman</option>
                <option value="nonbinary">Non-binary</option>
              </select>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="animate-fade-in">
            <h2 className="text-gradient">Your Vibe</h2>
            <p className={styles.subtitle}>Write a short bio to attract your match.</p>
            
            <div className={styles.formGroup}>
              <label>Bio</label>
              <textarea 
                className={styles.input} 
                rows={4} 
                placeholder="I love late night drives and deep conversations..."
              ></textarea>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="animate-fade-in">
            <h2 className="text-gradient">Your Aura</h2>
            <p className={styles.subtitle}>Pick up to 3 traits that define you.</p>
            
            <div className={styles.tagsContainer}>
              {AURA_TAGS.map(tag => (
                <button
                  key={tag}
                  onClick={() => toggleTag(tag)}
                  className={`${styles.tag} ${selectedTags.includes(tag) ? styles.tagSelected : ''}`}
                >
                  {tag}
                </button>
              ))}
            </div>
          </div>
        )}

        <div className={styles.actions}>
          {step > 1 && (
            <button className="btn-glass" onClick={() => setStep(step - 1)}>Back</button>
          )}
          <button 
            className={`btn-primary ${styles.nextBtn}`} 
            onClick={handleNext}
            style={{ marginLeft: step === 1 ? 'auto' : '0' }}
          >
            {step === 3 ? "Complete Profile" : "Continue"}
          </button>
        </div>
      </div>
    </main>
  );
}
